export type AdminScopeLevel = "organization" | "workspace" | "project" | "environment";

export type AdminAvailability = "required-product" | "optional-product" | "nested";

export type AdminOperationClassification = "read" | "write" | "destructive";

export type AdminOperationSource = "console" | "rest" | "mcp" | "sdk" | (string & {});

export type AdminJsonPrimitive = string | number | boolean | null;

export type AdminJsonValue =
  | AdminJsonPrimitive
  | AdminJsonValue[]
  | { [key: string]: AdminJsonValue };

export interface AdminJsonSchema {
  $id?: string;
  $ref?: string;
  $schema?: string;
  title?: string;
  description?: string;
  type?: string | string[];
  enum?: readonly unknown[];
  const?: unknown;
  default?: unknown;
  examples?: readonly unknown[];
  properties?: Readonly<Record<string, AdminJsonSchema>>;
  patternProperties?: Readonly<Record<string, AdminJsonSchema>>;
  required?: readonly string[];
  additionalProperties?: boolean | AdminJsonSchema;
  items?: AdminJsonSchema | readonly AdminJsonSchema[];
  prefixItems?: readonly AdminJsonSchema[];
  allOf?: readonly AdminJsonSchema[];
  anyOf?: readonly AdminJsonSchema[];
  oneOf?: readonly AdminJsonSchema[];
  not?: AdminJsonSchema;
  format?: string;
  pattern?: string;
  minimum?: number;
  maximum?: number;
  minLength?: number;
  maxLength?: number;
  minItems?: number;
  maxItems?: number;
  uniqueItems?: boolean;
  readOnly?: boolean;
  writeOnly?: boolean;
  deprecated?: boolean;
  [keyword: string]: unknown;
}

export interface AdminObjectSchema extends AdminJsonSchema {
  type: "object";
  properties?: Readonly<Record<string, AdminJsonSchema>>;
  required?: readonly string[];
  additionalProperties?: boolean | AdminJsonSchema;
}

export interface AdminScope {
  organizationId: string;
  workspaceId: string;
  projectId: string;
  environmentId: string;
  namespace?: string;
  region?: string;
}

export interface AdminActor {
  id: string;
  type?: "user" | "service" | "agent" | (string & {});
  displayName?: string;
  email?: string;
  roles?: readonly string[];
  permissions?: readonly string[];
  metadata?: Readonly<Record<string, unknown>>;
}

export interface AdminOperationContext {
  scope: AdminScope;
  actor: AdminActor;
  requestId: string;
  correlationId?: string;
  source: AdminOperationSource;
  idempotencyKey?: string;
  confirmationToken?: string;
  signal?: AbortSignal;
  now?: Date;
  metadata?: Readonly<Record<string, unknown>>;
}

export interface AdminRouteDefinition {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
}

export interface AdminSafetyDefinition {
  classification: AdminOperationClassification;
  idempotent?: boolean;
  requiresConfirmation?: boolean;
  audit?: "required" | "optional" | "none";
}

export interface AdminPaginationDefinition {
  mode: "cursor";
  defaultLimit?: number;
  maxLimit?: number;
  cursorInput?: string;
  limitInput?: string;
  itemsOutput?: string;
  nextCursorOutput?: string;
}

export interface AdminMcpDefinition {
  enabled?: boolean;
  name?: string;
  description?: string;
  readOnlyHint?: boolean;
  destructiveHint?: boolean;
  idempotentHint?: boolean;
  annotations?: Readonly<Record<string, unknown>>;
}

export interface AdminOperationDefinition<
  TInput = unknown,
  TOutput = unknown,
> {
  id: string;
  title: string;
  description: string;
  inputSchema?: AdminJsonSchema;
  outputSchema?: AdminJsonSchema;
  route: AdminRouteDefinition | string;
  permission: string;
  safety: AdminSafetyDefinition;
  pagination?: AdminPaginationDefinition;
  mcp?: AdminMcpDefinition | boolean;
  /** Phantom fields preserve handler inference without affecting manifests. */
  readonly __input?: TInput;
  readonly __output?: TOutput;
}

export interface AdminCapabilityOwner {
  moduleId: string;
  mountPath?: string;
}

export interface AdminDependencyDefinition {
  moduleId: string;
  required?: boolean;
  reason?: string;
}

export interface AdminNavigationDefinition {
  id: string;
  label: string;
  path: string;
  icon?: string;
  description?: string;
  order?: number;
  group?: string;
  parentId?: string;
  requiredPermission?: string;
}

export interface AdminHealthDefinition {
  operationId?: string;
  path?: string;
}

export interface AdminCapabilityManifest {
  schemaVersion: "1.0";
  id: string;
  displayName: string;
  version: string;
  description: string;
  category: string;
  availability: AdminAvailability;
  scopeLevels: readonly AdminScopeLevel[];
  owner?: AdminCapabilityOwner;
  dependencies?: readonly (AdminDependencyDefinition | string)[];
  navigation?: AdminNavigationDefinition | readonly AdminNavigationDefinition[];
  health?: AdminHealthDefinition;
  operations: readonly AdminOperationDefinition[];
}

export type AdminOperationInput<T extends AdminOperationDefinition> =
  T extends AdminOperationDefinition<infer TInput, unknown> ? TInput : never;

export type AdminOperationOutput<T extends AdminOperationDefinition> =
  T extends AdminOperationDefinition<unknown, infer TOutput> ? TOutput : never;

export interface AdminOperationResult<T = unknown> {
  ok?: true;
  data: T;
  page?: { nextCursor?: string | null; hasMore?: boolean };
  auditId?: string;
  warnings?: readonly string[];
  requestId?: string;
  correlationId?: string;
  meta?: Readonly<Record<string, unknown>>;
}

export interface AdminOperationError {
  ok: false;
  error: {
    code: string;
    message: string;
    status: number;
    details?: unknown;
    retryable?: boolean;
  };
  requestId?: string;
  correlationId?: string;
  auditId?: string;
}

export type AdminResult<T = unknown> = AdminOperationResult<T> | AdminOperationError;

export interface AdminOperationRequest<TInput = unknown> {
  input: TInput;
  context: AdminOperationContext;
}

export type AdminOperationHandler<TInput = unknown, TOutput = unknown> = (
  request: AdminOperationRequest<TInput>,
) => Promise<TOutput | AdminOperationResult<TOutput>> | TOutput | AdminOperationResult<TOutput>;

export type AdminOperationHandlers = Readonly<Record<string, AdminOperationHandler>>;

export interface AdminCapabilityAdapter<
  TManifest extends AdminCapabilityManifest = AdminCapabilityManifest,
> {
  readonly manifest: TManifest;
  readonly handlers: AdminOperationHandlers;
  invoke<T = unknown>(
    operationId: string,
    input: unknown,
    context: AdminOperationContext,
  ): Promise<AdminOperationResult<T>>;
  execute<T = unknown>(
    operationId: string,
    input: unknown,
    context: AdminOperationContext,
  ): Promise<AdminOperationResult<T>>;
}
import { AdminError } from "./errors.js";
import type {
  AdminCapabilityManifest,
  AdminJsonSchema,
  AdminOperationDefinition,
} from "./types.js";

export interface AdminValidationIssue {
  path: string;
  message: string;
  keyword?: string;
}

const ID_PATTERN = /^[a-z][a-z0-9-]*(?:\.[a-z0-9-]+)*$/;
const MODULE_PATTERN = /^[a-z][a-z0-9-]*$/;

function valueType(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (Number.isInteger(value)) return "integer";
  return typeof value;
}

function allowedTypes(schema: AdminJsonSchema): string[] {
  if (!schema.type) return [];
  return typeof schema.type === "string" ? [schema.type] : [...schema.type];
}

export function validateAdminValue(
  schema: AdminJsonSchema,
  value: unknown,
  path = "$",
): AdminValidationIssue[] {
  const issues: AdminValidationIssue[] = [];
  if (schema.const !== undefined && !Object.is(schema.const, value)) {
    issues.push({ path, message: "must equal the declared constant", keyword: "const" });
  }
  if (schema.enum && !schema.enum.some((candidate) => Object.is(candidate, value))) {
    issues.push({ path, message: "must be one of the declared values", keyword: "enum" });
  }

  const types = allowedTypes(schema);
  if (types.length > 0) {
    const actual = valueType(value);
    const matches = types.includes(actual) || (actual === "integer" && types.includes("number"));
    if (!matches) {
      return [{ path, message: `must be ${types.join(" or ")}`, keyword: "type" }];
    }
  }

  if (typeof value === "string") {
    if (schema.minLength !== undefined && value.length < schema.minLength) {
      issues.push({ path, message: `must contain at least ${schema.minLength} characters`, keyword: "minLength" });
    }
    if (schema.maxLength !== undefined && value.length > schema.maxLength) {
      issues.push({ path, message: `must contain at most ${schema.maxLength} characters`, keyword: "maxLength" });
    }
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) {
      issues.push({ path, message: "does not match the required pattern", keyword: "pattern" });
    }
  }

  if (typeof value === "number") {
    if (schema.minimum !== undefined && value < schema.minimum) {
      issues.push({ path, message: `must be at least ${schema.minimum}`, keyword: "minimum" });
    }
    if (schema.maximum !== undefined && value > schema.maximum) {
      issues.push({ path, message: `must be at most ${schema.maximum}`, keyword: "maximum" });
    }
  }

  if (Array.isArray(value)) {
    if (schema.minItems !== undefined && value.length < schema.minItems) {
      issues.push({ path, message: `must contain at least ${schema.minItems} items`, keyword: "minItems" });
    }
    if (schema.maxItems !== undefined && value.length > schema.maxItems) {
      issues.push({ path, message: `must contain at most ${schema.maxItems} items`, keyword: "maxItems" });
    }
    if (schema.uniqueItems) {
      const keys = value.map(stableSerialize);
      if (new Set(keys).size !== keys.length) issues.push({ path, message: "must contain unique items", keyword: "uniqueItems" });
    }
    if (schema.items && !Array.isArray(schema.items)) {
      value.forEach((item, index) => issues.push(...validateAdminValue(schema.items as AdminJsonSchema, item, `${path}[${index}]`)));
    }
  }

  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    const object = value as Record<string, unknown>;
    for (const key of schema.required ?? []) {
      if (!(key in object)) issues.push({ path: `${path}.${key}`, message: "is required", keyword: "required" });
    }
    for (const [key, item] of Object.entries(object)) {
      const propertySchema = schema.properties?.[key];
      if (propertySchema) {
        issues.push(...validateAdminValue(propertySchema, item, `${path}.${key}`));
      } else if (schema.additionalProperties === false) {
        issues.push({ path: `${path}.${key}`, message: "is not allowed", keyword: "additionalProperties" });
      } else if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
        issues.push(...validateAdminValue(schema.additionalProperties, item, `${path}.${key}`));
      }
    }
  }

  if (schema.allOf) for (const candidate of schema.allOf) issues.push(...validateAdminValue(candidate, value, path));
  if (schema.anyOf && !schema.anyOf.some((candidate) => validateAdminValue(candidate, value, path).length === 0)) {
    issues.push({ path, message: "must match at least one allowed schema", keyword: "anyOf" });
  }
  if (schema.oneOf && schema.oneOf.filter((candidate) => validateAdminValue(candidate, value, path).length === 0).length !== 1) {
    issues.push({ path, message: "must match exactly one allowed schema", keyword: "oneOf" });
  }
  return issues;
}

export function assertAdminValue(schema: AdminJsonSchema, value: unknown, label = "input"): void {
  const issues = validateAdminValue(schema, value);
  if (issues.length > 0) {
    throw new AdminError("invalid_argument", `Invalid administration ${label}.`, { details: { issues } });
  }
}

function stableSerialize(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableSerialize).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.entries(value as Record<string, unknown>).sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => `${JSON.stringify(key)}:${stableSerialize(item)}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "undefined";
}

function operationSchemas(operation: AdminOperationDefinition): [AdminJsonSchema, AdminJsonSchema] {
  const input = operation.inputSchema;
  const output = operation.outputSchema;
  if (!input || !output) throw new AdminError("invalid_argument", `Operation ${operation.id} must declare inputSchema and outputSchema.`);
  return [input, output];
}

function normalizedRoute(operation: AdminOperationDefinition): string {
  const raw = typeof operation.route === "string"
    ? operation.route.trim()
    : `${operation.route.method} ${operation.route.path}`;
  return raw
    .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, ":param")
    .replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, ":param");
}

export function validateAdminCapabilityManifest(manifest: AdminCapabilityManifest): AdminValidationIssue[] {
  const issues: AdminValidationIssue[] = [];
  if (manifest.schemaVersion !== "1.0") issues.push({ path: "$.schemaVersion", message: "must be 1.0" });
  if (!MODULE_PATTERN.test(manifest.id)) issues.push({ path: "$.id", message: "must be a stable lowercase module identifier" });
  if (!manifest.displayName.trim()) issues.push({ path: "$.displayName", message: "must not be empty" });
  if (!manifest.version.trim()) issues.push({ path: "$.version", message: "must not be empty" });
  if (manifest.scopeLevels.length === 0) issues.push({ path: "$.scopeLevels", message: "must contain at least one supported level" });
  if (manifest.availability === "nested" && !manifest.owner) issues.push({ path: "$.owner", message: "is required for nested modules" });
  if (manifest.availability !== "nested" && manifest.owner) issues.push({ path: "$.owner", message: "is only valid for nested modules" });
  const ids = new Set<string>();
  const routes = new Set<string>();
  manifest.operations.forEach((operation, index) => {
    if (!ID_PATTERN.test(operation.id) || !operation.id.startsWith(`${manifest.id}.`)) {
      issues.push({ path: `$.operations[${index}].id`, message: `must be namespaced with ${manifest.id}.` });
    }
    if (ids.has(operation.id)) issues.push({ path: `$.operations[${index}].id`, message: "duplicates another operation" });
    ids.add(operation.id);
    const route = normalizedRoute(operation);
    if (routes.has(route)) issues.push({ path: `$.operations[${index}].route`, message: "duplicates another route" });
    routes.add(route);
    if (!operation.permission.trim()) issues.push({ path: `$.operations[${index}].permission`, message: "must not be empty" });
    if (operation.safety.classification !== "read" && operation.safety.audit !== "required") {
      issues.push({ path: `$.operations[${index}].safety.audit`, message: "mutations must require audit" });
    }
    if (operation.safety.classification === "destructive" && !operation.safety.requiresConfirmation) {
      issues.push({ path: `$.operations[${index}].safety.requiresConfirmation`, message: "destructive operations must require confirmation" });
    }
    try { operationSchemas(operation); } catch (error) {
      issues.push({ path: `$.operations[${index}]`, message: error instanceof Error ? error.message : "schemas are invalid" });
    }
  });
  return issues;
}

export function assertAdminCapabilityManifest(manifest: AdminCapabilityManifest): void {
  const issues = validateAdminCapabilityManifest(manifest);
  if (issues.length > 0) throw new AdminError("invalid_argument", `Invalid admin capability manifest: ${manifest.id}.`, { details: { issues } });
}

export { stableSerialize };
import type { AdminCapabilityManifest } from "./types.js";

/** Defines a capability while preserving literal operation identifiers for consumers. */
export function defineAdminCapability<const TManifest extends AdminCapabilityManifest>(
  manifest: TManifest,
): TManifest {
  return manifest;
}
import type {
  AdminCapabilityAdapter,
  AdminCapabilityManifest,
  AdminOperationContext,
  AdminOperationHandlers,
  AdminOperationResult,
} from "./types.js";

export interface CreateAdminCapabilityAdapterOptions<
  TManifest extends AdminCapabilityManifest = AdminCapabilityManifest,
> {
  manifest: TManifest;
  handlers: AdminOperationHandlers;
}

function isResult(value: unknown): value is AdminOperationResult {
  return Boolean(value && typeof value === "object" && "data" in value && (value as { ok?: unknown }).ok !== false);
}

export function createAdminCapabilityAdapter<
  const TManifest extends AdminCapabilityManifest,
>(
  manifestOrOptions: TManifest | CreateAdminCapabilityAdapterOptions<TManifest>,
  providedHandlers?: AdminOperationHandlers,
): AdminCapabilityAdapter<TManifest> {
  const manifest = ("manifest" in manifestOrOptions
    ? manifestOrOptions.manifest
    : manifestOrOptions) as TManifest;
  const handlers = ("manifest" in manifestOrOptions
    ? manifestOrOptions.handlers
    : providedHandlers) ?? {};

  const invoke = async <T = unknown>(
    operationId: string,
    input: unknown,
    context: AdminOperationContext,
  ): Promise<AdminOperationResult<T>> => {
    const operation = manifest.operations.find((candidate) => candidate.id === operationId);
    if (!operation) {
      throw new Error(`Unknown admin operation: ${manifest.id}.${operationId}`);
    }
    const handler = handlers[operationId];
    if (!handler) {
      throw new Error(`No handler registered for admin operation: ${manifest.id}.${operationId}`);
    }
    const value = await handler({ input, context });
    return (isResult(value)
      ? value
      : {
          ok: true,
          data: value,
          requestId: context.requestId,
          correlationId: context.correlationId,
        }) as AdminOperationResult<T>;
  };

  return { manifest, handlers, invoke, execute: invoke };
}

export const createAdminAdapter = createAdminCapabilityAdapter;
import { AdminError } from "./errors.js";
import type { AdminCapabilityRegistry, AdminRegistryOperation } from "./registry.js";
import type { AdminJsonSchema, AdminObjectSchema } from "./types.js";

export interface AdminOpenApiOptions {
  title?: string;
  version?: string;
  description?: string;
  serverUrl?: string;
  securitySchemes?: Readonly<Record<string, unknown>>;
}

export interface AdminOpenApiDocument {
  openapi: "3.1.0";
  info: { title: string; version: string; description?: string };
  servers?: readonly { url: string }[];
  paths: Record<string, Record<string, unknown>>;
  components: Record<string, unknown>;
  tags: readonly Record<string, unknown>[];
  [extension: `x-${string}`]: unknown;
}

const ERROR_SCHEMA: AdminObjectSchema = {
  type: "object",
  properties: {
    ok: { type: "boolean", const: false },
    error: {
      type: "object",
      properties: {
        code: { type: "string" },
        message: { type: "string" },
        status: { type: "integer" },
        details: {},
        retryable: { type: "boolean" },
      },
      required: ["code", "message", "status"],
      additionalProperties: false,
    },
    requestId: { type: "string" },
    correlationId: { type: "string" },
  },
  required: ["ok", "error"],
  additionalProperties: false,
};

function route(entry: AdminRegistryOperation): { method: string; path: string; parameterNames: string[] } {
  const method = typeof entry.operation.route === "string"
    ? entry.operation.route.trim().split(/\s+/, 1)[0]!.toUpperCase()
    : entry.operation.route.method;
  const parameterNames: string[] = [];
  const path = entry.routePath
    .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (_, name: string) => { parameterNames.push(name); return `{${name}}`; })
    .replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (_, name: string) => { if (!parameterNames.includes(name)) parameterNames.push(name); return `{${name}}`; });
  return { method, path, parameterNames };
}

function withoutProperties(schema: AdminJsonSchema, names: readonly string[]): AdminJsonSchema | undefined {
  if (schema.type !== "object" || !schema.properties) return schema;
  const properties = Object.fromEntries(Object.entries(schema.properties).filter(([name]) => !names.includes(name)));
  if (Object.keys(properties).length === 0) return undefined;
  return { ...schema, properties, required: schema.required?.filter((name) => !names.includes(name)) };
}

function parametersFor(schema: AdminJsonSchema, parameterNames: readonly string[], includeQuery: boolean): Record<string, unknown>[] {
  const parameters: Record<string, unknown>[] = [];
  for (const name of parameterNames) {
    parameters.push({ name, in: "path", required: true, schema: schema.properties?.[name] ?? { type: "string" } });
  }
  if (includeQuery && schema.type === "object") {
    for (const [name, property] of Object.entries(schema.properties ?? {})) {
      if (!parameterNames.includes(name)) parameters.push({ name, in: "query", required: schema.required?.includes(name) ?? false, schema: property });
    }
  }
  return parameters;
}

export function createAdminOpenApiDocument(
  registry: AdminCapabilityRegistry,
  options: AdminOpenApiOptions = {},
): AdminOpenApiDocument {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const entry of registry.operations) {
    const { method, path, parameterNames } = route(entry);
    const input = entry.operation.inputSchema;
    const output = entry.operation.outputSchema;
    if (!input || !output) throw new AdminError("internal", `Operation ${entry.operation.id} has incomplete schemas.`);
    const isReadMethod = method === "GET" || method === "DELETE";
    const parameters = parametersFor(input, parameterNames, isReadMethod);
    const bodySchema = isReadMethod ? undefined : withoutProperties(input, parameterNames);
    const successSchema: AdminObjectSchema = {
      type: "object",
      properties: {
        ok: { type: "boolean", const: true },
        data: output,
        requestId: { type: "string" },
        correlationId: { type: "string" },
        auditId: { type: "string" },
      },
      required: ["ok", "data"],
      additionalProperties: true,
    };
    const operation: Record<string, unknown> = {
      operationId: entry.operation.id,
      summary: entry.operation.title,
      description: entry.operation.description,
      tags: [entry.manifest.displayName],
      security: [{ authFnSession: [] }, { authFnApiKey: [] }],
      ...(parameters.length ? { parameters } : {}),
      ...(bodySchema ? { requestBody: { required: true, content: { "application/json": { schema: bodySchema } } } } : {}),
      responses: {
        "200": { description: "Administration operation completed.", content: { "application/json": { schema: successSchema } } },
        "4XX": { description: "Administration request rejected.", content: { "application/json": { schema: { $ref: "#/components/schemas/AdminError" } } } },
        "5XX": { description: "Administration dependency or server failure.", content: { "application/json": { schema: { $ref: "#/components/schemas/AdminError" } } } },
      },
      "x-superfunctions-module": entry.moduleId,
      "x-superfunctions-capability-version": entry.manifest.version,
      "x-superfunctions-permission": entry.operation.permission,
      "x-superfunctions-safety": entry.operation.safety,
      ...(entry.operation.pagination ? { "x-superfunctions-pagination": entry.operation.pagination } : {}),
    };
    paths[path] ??= {};
    if (paths[path]![method.toLowerCase()]) throw new AdminError("conflict", `OpenAPI operation collision: ${method} ${path}.`);
    paths[path]![method.toLowerCase()] = operation;
  }

  return {
    openapi: "3.1.0",
    info: {
      title: options.title ?? "Super Console Administration API",
      version: options.version ?? "1.0.0",
      ...(options.description ? { description: options.description } : {}),
    },
    ...(options.serverUrl ? { servers: [{ url: options.serverUrl }] } : {}),
    paths,
    components: {
      schemas: { AdminError: ERROR_SCHEMA },
      securitySchemes: options.securitySchemes ?? {
        authFnSession: { type: "apiKey", in: "cookie", name: "authfn_session" },
        authFnApiKey: { type: "apiKey", in: "header", name: "Authorization" },
      },
    },
    tags: registry.manifests.map((manifest) => ({
      name: manifest.displayName,
      description: manifest.description,
      "x-superfunctions-module": manifest.id,
      ...(manifest.owner ? { "x-superfunctions-owner": manifest.owner } : {}),
    })),
    "x-superfunctions-enabled-modules": registry.enabledModuleIds,
    "x-superfunctions-registry-schema": "1.0",
  };
}

export const generateAdminOpenApi = createAdminOpenApiDocument;
import type { AdminOperationContext, AdminOperationDefinition } from "./types.js";

const SECRET_KEY = /(?:password|passwd|secret|token|authorization|cookie|credential|private[-_]?key|api[-_]?key|session|otp|code)/i;

export interface AdminAuditEvent {
  id: string;
  timestamp: string;
  actorId: string;
  actorType?: string;
  scope: AdminOperationContext["scope"];
  moduleId: string;
  operationId: string;
  classification: AdminOperationDefinition["safety"]["classification"];
  permission: string;
  source: string;
  requestId: string;
  correlationId?: string;
