  const ids = new Set<string>();
  const routes = new Set<string>();
  manifest.operations.forEach((operation, index) => {
    if (!ID_PATTERN.test(operation.id) || !operation.id.startsWith(`${manifest.id}.`)) {
      issues.push({ path: `$.operations[${index}].id`, message: `must be namespaced with ${manifest.id}.` });
    }
    if (ids.has(operation.id)) issues.push({ path: `$.operations[${index}].id`, message: "duplicates another operation" });
    ids.add(operation.id);
    const route = normalizedRoute(operation);
    if (routes.has(route)) issues.push({ path: `$.operations[${index}].route`, message: "duplicates another route" });
    routes.add(route);
    if (!operation.permission.trim()) issues.push({ path: `$.operations[${index}].permission`, message: "must not be empty" });
    if (operation.safety.classification !== "read" && operation.safety.audit !== "required") {
      issues.push({ path: `$.operations[${index}].safety.audit`, message: "mutations must require audit" });
    }
    if (operation.safety.classification === "destructive" && !operation.safety.requiresConfirmation) {
      issues.push({ path: `$.operations[${index}].safety.requiresConfirmation`, message: "destructive operations must require confirmation" });
    }
    for (const [kind, fields] of Object.entries(operation.redaction ?? {})) {
      const normalized = (fields ?? []).map((field) => field.trim().toLowerCase());
      if (normalized.some((field) => !field)) issues.push({ path: `$.operations[${index}].redaction.${kind}`, message: "must not contain blank field names" });
      if (new Set(normalized).size !== normalized.length) issues.push({ path: `$.operations[${index}].redaction.${kind}`, message: "must contain unique case-insensitive field names" });
    }
    if (operation.target) {
      if (!operation.target.resource.trim()) issues.push({ path: `$.operations[${index}].target.resource`, message: "must not be blank" });
      if (operation.target.idInput !== undefined && !operation.target.idInput.trim()) issues.push({ path: `$.operations[${index}].target.idInput`, message: "must not be blank" });
    }
    if (operation.mcp && typeof operation.mcp === "object") {
      const expectedRead = operation.safety.classification === "read";
      const expectedDestructive = operation.safety.classification === "destructive";
      if (operation.mcp.readOnlyHint !== undefined && operation.mcp.readOnlyHint !== expectedRead) issues.push({ path: `$.operations[${index}].mcp.readOnlyHint`, message: "must match the operation safety classification" });
      if (operation.mcp.destructiveHint !== undefined && operation.mcp.destructiveHint !== expectedDestructive) issues.push({ path: `$.operations[${index}].mcp.destructiveHint`, message: "must match the operation safety classification" });
      if (operation.mcp.idempotentHint !== undefined && operation.mcp.idempotentHint !== Boolean(operation.safety.idempotent)) issues.push({ path: `$.operations[${index}].mcp.idempotentHint`, message: "must match the operation idempotency declaration" });
    }
    try { operationSchemas(operation); } catch (error) {
      issues.push({ path: `$.operations[${index}]`, message: error instanceof Error ? error.message : "schemas are invalid" });
    }
  });
  return issues;
}

export function assertAdminCapabilityManifest(manifest: AdminCapabilityManifest): void {
  const issues = validateAdminCapabilityManifest(manifest);
  if (issues.length > 0) throw new AdminError("invalid_argument", `Invalid admin capability manifest: ${manifest.id}.`, { details: { issues } });
}

