      if (normalized.some((field) => !field)) issues.push({ path: `$.operations[${index}].redaction.${kind}`, message: "must not contain blank field names" });
      if (new Set(normalized).size !== normalized.length) issues.push({ path: `$.operations[${index}].redaction.${kind}`, message: "must contain unique case-insensitive field names" });
    }
    if (operation.target) {
