      if (operation.safety.classification === "destructive") {
        if (!operation.target.idInput) {
          issues.push({ path: `$.operations[${index}].target.idInput`, message: "destructive targets must declare an idInput" });
        } else if (!operation.inputSchema?.required?.includes(operation.target.idInput)) {
          issues.push({ path: `$.operations[${index}].inputSchema.required`, message: "must require the destructive target idInput" });
        }
