    if (operation.mcp && typeof operation.mcp === "object") {
      const expectedRead = operation.safety.classification === "read";
      const expectedDestructive = operation.safety.classification === "destructive";
      if (operation.mcp.readOnlyHint !== undefined && operation.mcp.readOnlyHint !== expectedRead) issues.push({ path: `$.operations[${index}].mcp.readOnlyHint`, message: "must match the operation safety classification" });
      if (operation.mcp.destructiveHint !== undefined && operation.mcp.destructiveHint !== expectedDestructive) issues.push({ path: `$.operations[${index}].mcp.destructiveHint`, message: "must match the operation safety classification" });
      if (operation.mcp.idempotentHint !== undefined && operation.mcp.idempotentHint !== Boolean(operation.safety.idempotent)) issues.push({ path: `$.operations[${index}].mcp.idempotentHint`, message: "must match the operation idempotency declaration" });
