import type { AdminOperationContext, AdminOperationDefinition } from "./types.js";

const SECRET_KEY = /(?:password|passwd|secret|token|authorization|cookie|credential|private[-_]?key|api[-_]?key|session|otp|code)/i;

export interface AdminAuditEvent {
  id: string;
  timestamp: string;
  actorId: string;
  actorType?: string;
  scope: AdminOperationContext["scope"];
  moduleId: string;
  operationId: string;
  classification: AdminOperationDefinition["safety"]["classification"];
  permission: string;
  source: string;
  requestId: string;
  correlationId?: string;
  idempotencyKey?: string;
  input: unknown;
  outcome: "succeeded" | "failed" | "denied" | "replayed";
  errorCode?: string;
  durationMs: number;
  metadata?: Readonly<Record<string, unknown>>;
}

export interface AdminAuditSink {
  write(event: AdminAuditEvent): Promise<void> | void;
}

export type AdminAuditIdFactory = () => string;

export function createAdminAuditId(): string {
  return `audit_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 12)}`;
}

export function redactAdminValue(
  value: unknown,
  sensitiveFields: readonly string[] = [],
  seen = new WeakSet<object>(),
): unknown {
  const explicit = new Set(sensitiveFields.map((field) => field.toLowerCase()));
  const visit = (current: unknown): unknown => {
    if (!current || typeof current !== "object") return current;
    if (seen.has(current)) return "[Circular]";
    seen.add(current);
    if (Array.isArray(current)) return current.map(visit);
    return Object.fromEntries(Object.entries(current as Record<string, unknown>).map(([key, item]) => [
      key,
      SECRET_KEY.test(key) || explicit.has(key.toLowerCase()) ? "[REDACTED]" : visit(item),
    ]));
  };
  return visit(value);
}

