import { describe, expect, it } from "vitest";
import { memoryAdapter } from "../../../../packages/db/src/testing/index.js";
import {
  authFnMultiRegionPlugin,
  authFnPasswordPlugin,
  type AuthFnConfig,
  type AuthFnRegionLookupRecord,
  type AuthFnRegionLookupStore,
  type AuthFnUserRecord,
} from "@authfn/core";
import { createAuthFnAdmin, createStaticAdminKeyAuthorizer } from "../index.js";

function createConfig(plugins: AuthFnConfig["plugins"] = []): AuthFnConfig {
  return {
    database: memoryAdapter({ debug: false }),
    namespace: "authfn",
    plugins,
  };
}

async function seedUser(
  config: AuthFnConfig,
  input: Partial<AuthFnUserRecord> & {
    id: string;
    primaryEmail: string;
    createdAt: Date;
  },
): Promise<AuthFnUserRecord> {
  const user: AuthFnUserRecord = {
    id: input.id,
    primaryEmail: input.primaryEmail,
    emailVerifiedAt: input.emailVerifiedAt ?? null,
    metadata: input.metadata,
    createdAt: input.createdAt,
    updatedAt: input.updatedAt ?? input.createdAt,
  };

  return config.database.create<AuthFnUserRecord>({
    model: "users",
    data: user as unknown as Record<string, unknown>,
    namespace: config.namespace,
  });
}

function authHeaders(token = "top-secret"): Record<string, string> {
  return {
    authorization: `Bearer ${token}`,
  };
}

describe("@authfn/admin", () => {
  it("requires an authorize hook before creating admin routes", () => {
    const config = createConfig();
    expect(() =>
      createAuthFnAdmin({
        authFnConfig: config,
        authorize: undefined as never,
      }),
    ).toThrow("AuthFn admin routes require an authorize hook");
  });

  it("rejects unauthorized admin requests with canonical AuthFn envelopes", async () => {
    const admin = createAuthFnAdmin({
      authFnConfig: createConfig(),
      authorize: () => false,
    });

    const response = await admin.router.handle(
      new Request("https://account.example.com/admin/users", {
        headers: {
          "x-request-id": "req_admin_denied",
        },
      }),
    );

    expect(response.status).toBe(401);
    await expect(response.json()).resolves.toMatchObject({
      ok: false,
      error: {
        code: "AUTHFN_ADMIN_UNAUTHORIZED",
        message: "Admin authorization required",
        retryable: false,
      },
      requestId: "req_admin_denied",
    });
  });

  it("lists users with stable cursor pagination", async () => {
    const config = createConfig();
    await seedUser(config, {
      id: "user_ada",
      primaryEmail: "ada@example.com",
      createdAt: new Date("2026-01-01T00:00:00.000Z"),
    });
    await seedUser(config, {
      id: "user_grace",
      primaryEmail: "grace@example.com",
      createdAt: new Date("2026-01-02T00:00:00.000Z"),
    });
    await seedUser(config, {
      id: "user_katherine",
      primaryEmail: "katherine@example.com",
      createdAt: new Date("2026-01-03T00:00:00.000Z"),
    });

    const admin = createAuthFnAdmin({
      authFnConfig: config,
      authorize: createStaticAdminKeyAuthorizer({ token: "top-secret" }),
    });

    const firstResponse = await admin.router.handle(
      new Request(
        "https://account.example.com/admin/users?limit=2&direction=asc",
        {
          headers: authHeaders(),
        },
      ),
    );
    expect(firstResponse.status).toBe(200);
    const firstBody = await firstResponse.json();
    expect(
      firstBody.data.users.map((user: AuthFnUserRecord) => user.id),
    ).toEqual(["user_ada", "user_grace"]);
    expect(firstBody.data.pageInfo.hasMore).toBe(true);
    expect(firstBody.data.pageInfo.nextCursor).toEqual(expect.any(String));

    const secondResponse = await admin.router.handle(
      new Request(
        `https://account.example.com/admin/users?limit=2&direction=asc&cursor=${firstBody.data.pageInfo.nextCursor}`,
        {
          headers: authHeaders(),
        },
      ),
    );
    expect(secondResponse.status).toBe(200);
    const secondBody = await secondResponse.json();
    expect(
      secondBody.data.users.map((user: AuthFnUserRecord) => user.id),
    ).toEqual(["user_katherine"]);
    expect(secondBody.data.pageInfo.hasMore).toBe(false);
  });

  it("hard-deletes a user by id and runs multi-region lookup cleanup hooks", async () => {
    const lookupDeletes: string[] = [];
    const lookupStore: AuthFnRegionLookupStore = {
      async getByIdentifier() {
        return null;
      },
      async putIfAbsent() {
        return { inserted: true };
      },
      async update(record: AuthFnRegionLookupRecord) {
        return record;
      },
      async deleteByIdentifier(identifier: string) {
        lookupDeletes.push(identifier);
      },
    };
    const config = createConfig([
      authFnPasswordPlugin(),
      authFnMultiRegionPlugin({ lookupStore }),
    ]);
    await seedUser(config, {
      id: "user_delete_me",
      primaryEmail: "DeleteMe@Example.com",
      createdAt: new Date("2026-01-01T00:00:00.000Z"),
    });
    await config.database.create({
      model: "password_credentials",
      data: {
        id: "pwd_1",
        userId: "user_delete_me",
        passwordHash: "scrypt$hash",
        createdAt: new Date("2026-01-01T00:00:00.000Z"),
        updatedAt: new Date("2026-01-01T00:00:00.000Z"),
      },
      namespace: config.namespace,
    });
    await config.database.create({
      model: "sessions",
      data: {
        id: "session_1",
        userId: "user_delete_me",
        tokenHash: "token_hash",
        methods: ["password"],
        expiresAt: new Date("2026-02-01T00:00:00.000Z"),
        createdAt: new Date("2026-01-01T00:00:00.000Z"),
        updatedAt: new Date("2026-01-01T00:00:00.000Z"),
      },
      namespace: config.namespace,
    });
    await config.database.create({
      model: "region_profiles",
      data: {
        id: "region_profile_1",
        userId: "user_delete_me",
        regionId: "insouth",
        authority: "https://account-insouth.example.com",
        createdAt: new Date("2026-01-01T00:00:00.000Z"),
        updatedAt: new Date("2026-01-01T00:00:00.000Z"),
      },
      namespace: config.namespace,
    });

    const admin = createAuthFnAdmin({
      authFnConfig: config,
      authorize: () => ({ allowed: true, actorId: "admin_1" }),
    });

    const response = await admin.router.handle(
      new Request("https://account.example.com/admin/users/user_delete_me", {
        method: "DELETE",
      }),
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toMatchObject({
      ok: true,
      data: {
        deleted: true,
        userId: "user_delete_me",
        primaryEmail: "DeleteMe@Example.com",
        counts: {
          users: 1,
          sessions: 1,
          passwordCredentials: 1,
          regionProfiles: 1,
        },
      },
    });
    await expect(
      config.database.findOne({
        model: "users",
        where: [{ field: "id", operator: "eq", value: "user_delete_me" }],
        namespace: config.namespace,
      }),
    ).resolves.toBeNull();
    await expect(
      config.database.findMany({
        model: "sessions",
        where: [{ field: "userId", operator: "eq", value: "user_delete_me" }],
        namespace: config.namespace,
      }),
    ).resolves.toHaveLength(0);
    await expect(
      config.database.findMany({
        model: "password_credentials",
        where: [{ field: "userId", operator: "eq", value: "user_delete_me" }],
        namespace: config.namespace,
      }),
    ).resolves.toHaveLength(0);
    await expect(
      config.database.findMany({
        model: "region_profiles",
        where: [{ field: "userId", operator: "eq", value: "user_delete_me" }],
        namespace: config.namespace,
      }),
    ).resolves.toHaveLength(0);
    expect(new Set(lookupDeletes)).toEqual(new Set(["deleteme@example.com"]));
  });
import { describe, expect, it, vi } from "vitest";
import {
  authFnAdminCapability,
  createAuthFnAdminAdapter,
  type AuthFnAdminService,
  type AuthFnAdminServiceRequest,
} from "../index.js";

const context = {
  scope: {
    organizationId: "org_1",
    workspaceId: "workspace_1",
    projectId: "project_1",
    environmentId: "environment_1",
    namespace: "auth_tenant_1",
    region: "in-south",
  },
  actor: { id: "operator_1", type: "user" as const, permissions: ["*"] },
  requestId: "request_1",
  correlationId: "correlation_1",
  source: "console" as const,
  idempotencyKey: "idempotency_1",
};

describe("@authfn/admin capability", () => {
  it("extends the existing admin routes with the full operator contract", () => {
    expect(authFnAdminCapability.availability).toBe("required-product");
    expect(
      authFnAdminCapability.operations.some(
        (operation) => operation.id === "authfn.users.list",
      ),
    ).toBe(true);
    expect(
      authFnAdminCapability.operations.find(
        (operation) => operation.id === "authfn.users.delete-user",
      ),
    ).toMatchObject({
      safety: {
        classification: "destructive",
        requiresConfirmation: true,
        audit: "required",
      },
    });
  });

  it("binds collection invitations and destructive user targets explicitly", () => {
    const inviteUser = authFnAdminCapability.operations.find(
      (operation) => operation.id === "authfn.users.invite-user",
    );
    expect(inviteUser).toMatchObject({
      target: { resource: "users", collection: true },
    });
    expect(inviteUser?.inputSchema?.required).toBeUndefined();
    expect(
      authFnAdminCapability.operations.find(
        (operation) => operation.id === "authfn.users.delete-user",
      ),
    ).toMatchObject({
      safety: { classification: "destructive", requiresConfirmation: true },
      target: { resource: "users", idInput: "id" },
      inputSchema: { required: ["id"] },
    });
  });

  it("delegates the operation and complete scope to the injected AuthFn service", async () => {
    const execute = vi.fn(async (request: AuthFnAdminServiceRequest) => ({
      ok: true as const,
      data: {
        operationId: request.operationId,
        namespace: request.context.scope.namespace,
        region: request.context.scope.region,
      },
    }));
    const service: AuthFnAdminService = { execute };
    const adapter = createAuthFnAdminAdapter(service);

    const result = await adapter.execute(
      "authfn.users.list",
      { limit: 25 },
      context,
    );

    expect(result.data).toEqual({
      operationId: "authfn.users.list",
      namespace: "auth_tenant_1",
      region: "in-south",
    });
    expect(execute).toHaveBeenCalledWith({
      operationId: "authfn.users.list",
      input: { limit: 25 },
      context,
    });
  });
});

